---level1 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl1_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end		game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)				game.pauseLogic()		if dialog.show("Level1-1", faceRenzhen) ==1 then break end		game.resumeLogic()				script.delay(1)		if dialog.show("~~~~~~", facePutong) ==1 then break end		role.lookLeftRight()		script.delay(3)		if dialog.show("Level1-2", faceManyi) ==1 then break end		sound.play("43-1")		if dialog.show("Level1-3", faceBujie) ==1 then break end		if dialog.show("Level1-4", facePutong) ==1 then break end		if dialog.show("Level1-5", faceZhoumei) ==1 then break end		sound.play("50-1")		camera.setFollowRoleMode(false)		camera.gotoPosition(475,1050)		if dialog.show("Level1-6", faceManyi) ==1 then break end		camera.gotoRole()		camera.setFollowRoleMode(true)		game.showTutorialDiagram(1)		if dialog.showMinTime("Level1-7", faceWeixiao,4) ==1 then break end		game.showTutorialDiagram(0)				---start playing demo		dialog.setSkipEnabled(false)		isPlayingDemo = true		isSkip = false				game.setReplayMode()		game.loadTutorialRep("Rep_rd_1")		replay.skipNonControlFrames()		dialog.showFixedTime("Level1-8", faceRenzhen, 2)		script.delay(0.5)		dialog.showFixedTime("Level1-9", faceShijin, 2.8)	until trueendif isSkip then	camera.gotoRole()	camera.setFollowRoleMode(true)	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()endonRoleReachedMoon = function()     if isPlayingDemo then        replay.pause()		game.setPlayMode()		game.setUserInputEnabled(false)        role.loadState()        script.delay(1.2)        dialog.show("Level1-10", faceDeyi)        game.setUserInputEnabled(true)        game.restartTiming()		role.setIdleActionEnabled(true)        isPlayingDemo = false        countFail = 0        --set story viewed flag        global.setBool("lvl1_b1")    else        game.pauseLogic()		sound.play("54-1")        dialog.show("Level1-11", faceManyi)        game.success()    endendonRoleDied = function()    countFail = countFail + 1    game.setUserInputEnabled(false)    if countFail <= 1 then		sound.play("51-2")        dialog.show("Level1-12", faceBujie)    else		sound.play("58-1")        dialog.show("Level1-13", faceShengqi)    end    game.setUserInputEnabled(true)    role.loadState()end